const minute=t=>{const [h,m]=t.split(':').map(Number);return h*60+m+(h<6?1440:0)};
fetch('/my-day/data.json?v=2').then(r=>r.json()).then(acts=>{
 document.querySelector('#timeline-list').innerHTML=acts.map((a,i)=>{
 const next=acts[i+1],gap=next?minute(next.start)-minute(a.end):null;
 return `<a class="stop" href="#${a.key}"><span class="stop-time">${a.start}—${a.end}${a.actualNote?'<small>SCHEDULED TIME</small>':''}${minute(a.start)>=1440?'<small>SUNDAY 25 OCT</small>':''}</span><span class="stop-index">${String(i+1).padStart(2,'0')}</span><span><span class="stop-name">${a.name}</span>${a.actualNote?`<span class="actual-note">${a.actualNote}</span>`:''}<span class="stop-venue">${a.venue} · ${a.actualNote?'ended after one song':(minute(a.end)-minute(a.start))+' min'}</span></span><span class="stop-arrow">↗</span></a>${next?`<div class="gap ${gap===0?'tight':''}">${a.actualNote?'Set ended early · actual finish time unrecorded':gap===0?'No transfer time · leave early / arrive late':gap+' min gap · '+(a.venue===next.venue?'stay at '+a.venue:a.venue+' → '+next.venue)}</div>`:''}`;
 }).join('');
 const imageSources={kelly:['Artist press photo · Left of the Dial','https://leftofthedial.nl/acts/kelly-no-brakes/'],really:['Press image · Prescription PR','https://www.prescriptionmusicpruk.com/press-releases/really-good-time-share-new-single-bob-dylan-was-on-pawn-stars-in-2010'],mleko:['Artist image · Heist or Hit','https://www.heistorhit.com/artists/mleko/'],snayx:['Artist image · The Deaf Institute','https://www.thedeafinstitute.co.uk/event/snayx/'],plantoid:['Artist image · TJPL News','https://www.tjplnews.com/post/plantoid-brighton-psychedelic-rock-revolution'],iguana:['Artist image · MP3s & NPCs','https://mp3sandnpcs.com/home/dutch-garage-rock-band-iguana-death-cult-announce-new-album-echo-palace-share-new-song'],dove:['Photo: Xander Lewis · courtesy of the artist / WXPN','https://xpn.org/press-play-12-5-2025/'],mike:['Mike D 5D · photo: Sam Finelli / Nasty Little Man','https://www.nastylittleman.com/2026/06/08/mike-d-5d-debut-album-thank-you-out-august-28th/'],painkiller:['Artist photo · FOCUS Wales','https://focuswales.com/artists/painkiller/'],alien:['Artist image · Bandcamp','https://alienchicks.bandcamp.com/'],cowboy:['Photo: Lucy Craig · Prescription PR','https://prescriptionmusicpr.squarespace.com/press-releases/cowboy-hunters-share-highly-requested-single-punched-in-the-head']};
 document.querySelector('#artist-list').innerHTML=acts.map((a,i)=>`<article class="artist" id="${a.key}"><figure class="artist-image"><img loading="lazy" src="/my-day/assets/${a.key==='kelly'?'kelly-press':a.key==='dove'?'dove-xander-lewis':a.key==='mike'?'mike-5d-sam-finelli':a.key==='painkiller'?'painkiller-focus-wales':a.key}.jpg" alt="${a.key==='kelly'?'Kelly No Brakes duo press portrait':a.key==='mike'?'Mike D and his 5D band in blue jumpsuits':a.name}"><figcaption><a href="${imageSources[a.key][1]}" target="_blank" rel="noopener">${imageSources[a.key][0]} ↗</a></figcaption></figure><div><p class="artist-number">${String(i+1).padStart(2,'0')} / YOUR SATURDAY</p><h3>${a.name}</h3><p class="artist-tag">${a.tag}</p>${a.actualNote?`<aside class="actual-callout"><strong>ONE SONG, THEN EVACUATION</strong><p>${a.actualNote}</p><small>From my day · exact finish time unrecorded. Times below show the scheduled slot.</small></aside>`:''}<div class="artist-meta">${a.start}—${a.end} ${minute(a.start)>=1440?'· Sunday ': '· '}${a.venue} / ${a.street}</div><p class="artist-bio">${a.bio}</p>${a.videoUrl?`<aside class="video-memory"><span class="eyebrow">FROM MY DAY / VIDEO</span><h4>${a.name} · live at Mutations.</h4>${a.videoTime?`<p>Recorded ${a.videoTime}. Matched to this set from the video’s recording time.</p>`:''}${a.youtubeId?`<iframe class="video-player${a.videoFormat==='landscape'?' video-landscape':''}" src="https://www.youtube-nocookie.com/embed/${a.youtubeId}" title="${a.name} — my Mutations Festival video" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`:''}<a href="${a.videoUrl}" target="_blank" rel="noopener">Watch on YouTube ↗</a></aside>`:''}<p style="font-size:11px;color:var(--muted)">A listening starting point: <b>${a.listen}</b></p><div class="links"><a href="https://open.spotify.com/search/${encodeURIComponent(a.name==='Painkiller'?'Painkiller Tom Rees':a.name)}" target="_blank" rel="noopener">Find on Spotify ↗</a><a href="${a.source}" target="_blank" rel="noopener">Profile source ↗</a><a href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(a.venue+' Brighton '+a.street)}" target="_blank" rel="noopener">Venue map ↗</a></div></div></article>`).join('');
}).catch(()=>{document.querySelector('#timeline-list').textContent='The schedule could not load. Please refresh the page.'});
